    color: ${fC.titleColor};
  }
  .cluster-label span p {
    background-color: transparent;
  }

  .label text,span {
    fill: ${fC.nodeTextColor||fC.textColor};
    color: ${fC.nodeTextColor||fC.textColor};
  }

  .node rect,
  .node circle,
  .node ellipse,
  .node polygon,
