    stroke: ${fC.nodeBorder};
    stroke-width: ${fC.strokeWidth??1}px;
  }
  .rough-node .label text , .node .label text, .image-shape .label, .icon-shape .label {
    text-anchor: middle;
  }

  .node .katex path {
    fill: #000;
    stroke: #000;
    stroke-width: 1px;
  }

  .rough-node .label,.node .label, .image-shape .label, .icon-shape .label {
    text-align: center;
  }
  .node.clickable {
    cursor: pointer;
  }


  .root .anchor path {
    fill: ${fC.lineColor} !important;
    stroke-width: 0;
    stroke: ${fC.lineColor};
  }

  .arrowheadPath {
    fill: ${fC.arrowheadColor};
  }

  .edgePaths .path {
    stroke: ${fC.lineColor};
    stroke-width: ${fC.strokeWidth??2}px;
  }

  .flowchart-link {
    stroke: ${fC.lineColor};
    fill: none;
  }

