  .section0 {
    fill: ${fC.sectionBkgColor};
  }

  .section2 {
    fill: ${fC.sectionBkgColor2};
  }

  .section1,
  .section3 {
    fill: ${fC.altSectionBkgColor};
    opacity: 0.2;
  }

  .sectionTitle0 {
    fill: ${fC.titleColor};
  }

  .sectionTitle1 {
    fill: ${fC.titleColor};
  }

  .sectionTitle2 {
    fill: ${fC.titleColor};
  }

  .sectionTitle3 {
