  fill: ${fC.mainBkg};
  opacity: 0.5;
}

.classLabel .label {
  fill: ${fC.nodeBorder};
  font-size: 10px;
}

.relation {
  stroke: ${fC.lineColor};
  stroke-width: ${fC.strokeWidth};
  fill: none;
}

.dashed-line{
  stroke-dasharray: 3;
}

.dotted-line{
  stroke-dasharray: 1 2;
}

