defs [id$="-barbEnd"] {
    fill: ${fC.transitionColor};
    stroke: ${fC.transitionColor};
  }
g.stateGroup text {
  fill: ${fC.nodeBorder};
  stroke: none;
  font-size: 10px;
}
g.stateGroup text {
  fill: ${fC.textColor};
  stroke: none;
  font-size: 10px;

}
g.stateGroup .state-title {
  font-weight: bolder;
  fill: ${fC.stateLabelColor};
}

g.stateGroup rect {
  fill: ${fC.mainBkg};
  stroke: ${fC.nodeBorder};
}

g.stateGroup line {
  stroke: ${fC.lineColor};
  stroke-width: ${fC.strokeWidth||1};
}

.transition {
  stroke: ${fC.transitionColor};
  stroke-width: ${fC.strokeWidth||1};
  fill: none;
}

.stateGroup .composit {
  fill: ${fC.background};
  border-bottom: 1px
}

.stateGroup .alt-composit {
  fill: #e0e0e0;
  border-bottom: 1px
}

.state-note {
  stroke: ${fC.noteBorderColor};
  fill: ${fC.noteBkgColor};

  text {
    fill: ${fC.noteTextColor};
    stroke: none;
    font-size: 10px;
  }
}

.stateLabel .box {
  stroke: none;
  stroke-width: 0;
  fill: ${fC.mainBkg};
  opacity: 0.5;
}

.edgeLabel .label rect {
  fill: ${fC.labelBackgroundColor};
  opacity: 0.5;
}
.edgeLabel {
  background-color: ${fC.edgeLabelBackground};
  p {
    background-color: ${fC.edgeLabelBackground};
  }
  rect {
    opacity: 0.5;
    background-color: ${fC.edgeLabelBackground};
    fill: ${fC.edgeLabelBackground};
  }
  text-align: center;
}
.edgeLabel .label text {
  fill: ${fC.transitionLabelColor||fC.tertiaryTextColor};
}
.label div .edgeLabel {
  color: ${fC.transitionLabelColor||fC.tertiaryTextColor};
}

.stateLabel text {
  fill: ${fC.stateLabelColor};
  font-size: 10px;
  font-weight: bold;
}

.node circle.state-start {
  fill: ${fC.specialStateColor};
  stroke: ${fC.specialStateColor};
}

.node .fork-join {
  fill: ${fC.specialStateColor};
  stroke: ${fC.specialStateColor};
}

.node circle.state-end {
  fill: ${fC.innerEndBackground};
  stroke: ${fC.background};
  stroke-width: 1.5
}
.end-state-inner {
  fill: ${fC.compositeBackground||fC.background};
  // stroke: ${fC.background};
  stroke-width: 1.5
}

.node rect {
  fill: ${fC.stateBkg||fC.mainBkg};
  stroke: ${fC.stateBorder||fC.nodeBorder};
  stroke-width: ${fC.strokeWidth||1}px;
}
.node polygon {
  fill: ${fC.mainBkg};
  stroke: ${fC.stateBorder||fC.nodeBorder};;
  stroke-width: ${fC.strokeWidth||1}px;
}
[id$="-barbEnd"] {
  fill: ${fC.lineColor};
}

.statediagram-cluster rect {
  fill: ${fC.compositeTitleBackground};
  stroke: ${fC.stateBorder||fC.nodeBorder};
  stroke-width: ${fC.strokeWidth||1}px;
}

.cluster-label, .nodeLabel {
  color: ${fC.stateLabelColor};
  // line-height: 1;
}

.statediagram-cluster rect.outer {
  rx: 5px;
  ry: 5px;
}
.statediagram-state .divider {
  stroke: ${fC.stateBorder||fC.nodeBorder};
}

.statediagram-state .title-state {
  rx: 5px;
  ry: 5px;
}
.statediagram-cluster.statediagram-cluster .inner {
  fill: ${fC.compositeBackground||fC.background};
}
.statediagram-cluster.statediagram-cluster-alt .inner {
  fill: ${fC.altBackground?fC.altBackground:`#efefef`};
}

.statediagram-cluster .inner {
  rx:0;
  ry:0;
}

.statediagram-state rect.basic {
  rx: 5px;
  ry: 5px;
}
.statediagram-state rect.divider {
  stroke-dasharray: 10,10;
  fill: ${fC.altBackground?fC.altBackground:`#efefef`};
}

.note-edge {
  stroke-dasharray: 5;
}

.statediagram-note rect {
  fill: ${fC.noteBkgColor};
  stroke: ${fC.noteBorderColor};
  stroke-width: 1px;
  rx: 0;
  ry: 0;
}
.statediagram-note rect {
  fill: ${fC.noteBkgColor};
  stroke: ${fC.noteBorderColor};
  stroke-width: 1px;
  rx: 0;
  ry: 0;
}

.statediagram-note text {
  fill: ${fC.noteTextColor};
}

.statediagram-note .nodeLabel {
  color: ${fC.noteTextColor};
}
.statediagram .edgeLabel {
  color: red; // ${fC.noteTextColor};
}

[id$="-dependencyStart"], [id$="-dependencyEnd"] {
  fill: ${fC.lineColor};
  stroke: ${fC.lineColor};
  stroke-width: ${fC.strokeWidth||1};
}

.statediagramTitleText {
  text-anchor: middle;
  font-size: 18px;
  fill: ${fC.textColor};
}

[data-look="neo"].statediagram-cluster rect {
  fill: ${fC.mainBkg};
  stroke: ${fC.useGradient?`url(`+fC.svgId+`-gradient)`:fC.stateBorder||fC.nodeBorder};
  stroke-width: ${fC.strokeWidth??1};
}
[data-look="neo"].statediagram-cluster rect.outer {
  rx: ${fC.radius}px;
  ry: ${fC.radius}px;
  filter: ${fC.dropShadow?fC.dropShadow.replace(`url(#drop-shadow)`,`url(${fC.svgId}-drop-shadow)`):`none`}
