  .node .label {
    text-align: center;
  }
  .node.clickable {
    cursor: pointer;
  }

  .arrowheadPath {
    fill: ${fC.arrowheadColor};
  }

  .edgePaths .path {
    stroke: ${fC.lineColor};
    stroke-width: 2.0px;
  }

  .flowchart-link {
    stroke: ${fC.lineColor};
    fill: none;
  }

  .edgeLabel {
    background-color: ${fC.edgeLabelBackground};
    /*
     * This is for backward compatibility with existing code that didn't
     * add a \`<p>\` around edge labels.
     *
     * TODO: We should probably remove this in a future release.
