    p {
      margin: 0;
      padding: 0;
      display: inline;
    }
    rect {
      opacity: 0.5;
      background-color: ${fC.edgeLabelBackground};
      fill: ${fC.edgeLabelBackground};
    }
    text-align: center;
  }

