    // fill: ${wYt(fC.mainBkg,.5)};
    fill: ${wYt(fC.clusterBkg,.5)};
    stroke: ${wYt(fC.clusterBorder,.2)};
    box-shadow: rgba(50, 50, 93, 0.25) 0px 13px 27px -5px, rgba(0, 0, 0, 0.3) 0px 8px 16px -8px;
    stroke-width: 1px;
  }

  .cluster text {
    fill: ${fC.titleColor};
  }

  .cluster span {
    color: ${fC.titleColor};
  }
  /* .cluster div {
    color: ${fC.titleColor};
  } */

  div.mermaidTooltip {
    position: absolute;
    text-align: center;
    max-width: 200px;
    padding: 2px;
    font-family: ${fC.fontFamily};
    font-size: 12px;
    background: ${fC.tertiaryColor};
    border: 1px solid ${fC.border2};
    border-radius: 2px;
    pointer-events: none;
    z-index: 100;
  }

