.ishikawa .ishikawa-spine,
.ishikawa .ishikawa-branch,
.ishikawa .ishikawa-sub-branch {
  stroke: ${fC.lineColor};
  stroke-width: 2;
  fill: none;
}

.ishikawa .ishikawa-sub-branch {
  stroke-width: 1;
}

.ishikawa .ishikawa-arrow {
  fill: ${fC.lineColor};
}

.ishikawa .ishikawa-head {
  fill: ${fC.mainBkg};
  stroke: ${fC.lineColor};
  stroke-width: 2;
}

.ishikawa .ishikawa-label-box {
  fill: ${fC.mainBkg};
  stroke: ${fC.lineColor};
  stroke-width: 2;
}

.ishikawa text {
  font-family: ${fC.fontFamily};
  font-size: ${fC.fontSize};
  fill: ${fC.textColor};
}

.ishikawa .ishikawa-head-label {
  font-weight: 600;
  text-anchor: middle;
  dominant-baseline: middle;
  font-size: 14px;
}

.ishikawa .ishikawa-label {
  text-anchor: end;
}

.ishikawa .ishikawa-label.cause {
  text-anchor: middle;
  dominant-baseline: middle;
}

.ishikawa .ishikawa-label.align {
  text-anchor: end;
  dominant-baseline: middle;
}

.ishikawa .ishikawa-label.up {
  dominant-baseline: baseline;
}

.ishikawa .ishikawa-label.down {
  dominant-baseline: hanging;
